entries[124246] = { ["name"] = "Tracht des Klauenschwurs", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 165 / 165\nKlassen: Druide\nKriegsgewand des Klauenschwurs (0/5)\nTracht des Klauenschwurs\nStulpen des Klauenschwurs\nHelm des Klauenschwurs\nGamaschen des Klauenschwurs\nMantelung des Klauenschwurs\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gleichgewicht: 'Mondfeuer' und 'Sonnenfeuer' haben eine Chance, einen Feendrachen zu beschwören, der Euch 30 Sek. lang im Kampf unterstützt.\n(2) Set Wildheit: Erhöht die Chance, dass 'Omen der Klarsicht' ausgelöst wird, und erhöht Eure maximale Energie in Katzengestalt um 20.\n(2) Set Wächter: 'Eisenfell' erhöht zusätzlich Eure erhaltene Heilung um 20%, solange der Effekt aktiv ist.\n(2) Set Wiederherstellung: 'Blühendes Leben' hat eine Chance von 5%, zu erblühen, wenn der Effekt tickt.\n(4) Set Gleichgewicht: Wenn ein Feendrache beschworen wurde, werden Euer Arkan- und Naturschaden 30 Sek. lang um 6% erhöht.\n(4) Set Wildheit: Während 'Omen der Klarsicht' aktiv ist, erzeugt Eure nächste Fähigkeit in Katzengestalt bei ihrem Einsatz 100% ihrer Energiekosten.\n(4) Set Wächter: Während 'Eisenfell' aktiv ist, sind die Kosten von 'Rasende Regeneration' um 50% verringert.\n(4) Set Wiederherstellung: 'Blühendes Leben' kann auf zwei Zielen gleichzeitig aktiv sein.\nVerkaufspreis:" }
entries[124247] = { ["name"] = "Robe des Taifunauges", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 165 / 165\nKlassen: Mönch\nSchlachttücher des Taifunauges (0/5)\nRobe des Taifunauges\nFaustwickel des Taifunauges\nMaske des Taifunauges\nBeinwickel des Taifunauges\nMantelung des Taifunauges\nAltes Set: Bonus ist nicht aktiv\n(2) Set Braumeister: Erhöht die Chance, dass Eure 'Gabe des Ochsen' eine heilende Sphäre beschwört, um 2%.\n(2) Set Windläufer: Euer 'Tritt der aufgehenden Sonne' gewährt 2 Aufladungen von 'Meisterhafte Schläge'. 'Meisterhafte Schläge' erhöht bei Einsatz Eurer nächsten Schadensfähigkeit Eure Meisterschaft um 10%.\n(2) Set Nebelwirker: Euer 'Erneuernder Nebel' belegt Euer erstes Ziel zusätzlich mit 'Verlängertes Leben', was es sofort um (26.45% der Zaubermacht) heilt und sämtliche von ihm erhaltene Heilung 12 Sek. lang um 15% erhöht.\n(4) Set Braumeister: Immer wenn Ihr eine 'Heilende Sphäre' einsammelt, wird die verbleibende Abklingzeit von 'Eisenhautgebräu' und 'Reinigendes Gebräu' um 1 Sek. verringert.\n(4) Set Windläufer: Eure 'Furorfäuste' gewähren 3 Aufladungen von 'Meisterhafte Schläge' und erhöhen Eure maximale Energie um 20.\n(4) Set Nebelwirker: Wenn Ihr mit 'Einhüllender Nebel' oder 'Beleben' heilt, werden 50% der Heilung zusätzlich auf Ziele gewirkt, die mit Eurem Effekt 'Verlängertes Leben' belegt sind.\nVerkaufspreis:" }
entries[124248] = { ["name"] = "Brustschutz der Dämonenklinge", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 165 / 165\nKlassen: Schurke\nRüstung der Dämonenklinge (0/5)\nBrustschutz der Dämonenklinge\nHandschuhe der Dämonenklinge\nKapuze der Dämonenklinge\nGamaschen der Dämonenklinge\nSchiftung der Dämonenklinge\nAltes Set: Bonus ist nicht aktiv\n(2) Set Meucheln: Dir kritische Trefferchance von 'Blutung' ist bei Gegnern, deren Gesundheit unter 35% liegt, um 30% erhöht.\n(2) Set Gesetzlosigkeit: Während 'Schicksalswürfel' aktiv ist, habt Ihr eine Chance, 4 Sek. lang den Effekt 'Adrenalinrausch' zu erhalten. (Procchance: 8%)\n(2) Set Täuschung: Der Einsatz Eurer Fähigkeit 'Verschwinden' gewährt jetzt 5 Combopunkte und erhöht sämtlichen verursachten Schaden 10 Sek. lang um 30%.\n(4) Set Meucheln: Euer 'Verstümmeln' erzeugt nun einen zusätzlichen Combopunkt, wenn die Gesundheit des Gegners unter 35% liegt.\n(4) Set Gesetzlosigkeit: Erhöht Euren verursachten Schaden, während 'Adrenalinrausch' aktiv ist, um 15%. (Procchance: 8%)\n(4) Set Täuschung: 'Ausweiden' und 'Nachtklinge' verringern die Abklingzeit von 'Verschwinden' um 1 Sek. pro verbrauchtem Combopunkt.\nVerkaufspreis:" }
