entries[124327] = { ["name"] = "Stulpen des Dämonenblicks", ["text"] = "Wird beim Aufheben gebunden\nHände Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 55 / 55\nKlassen: Todesritter\nRüstung des Dämonenblicks (0/5)\nBrustplatte des Dämonenblicks\nStulpen des Dämonenblicks\nHelm des Dämonenblicks\nBeinplatten des Dämonenblicks\nSchulterstücke des Dämonenblicks\nAltes Set: Bonus ist nicht aktiv\n(2) Set Blut: 'Herzstoß' hat eine Chance von 25%, zusätzliche 10 Runenmacht zu erzeugen.\n(2) Set Frost: Wenn Ihr mit 'Auslöschen' einen kritischen Treffer erzielt, erhaltet Ihr 12 Sek. lang 3% Tempo. Wenn Ihr mit 'Froststoß' einen kritischen Treffer erzielt, wird Euer kritischer Schaden 12 Sek. lang um 6% erhöht.\n(2) Set Unheilig: Erhöht den verursachten Schaden Eurer Begleiter um 20%.\n(4) Set Blut: Verringert die Kosten von 'Todesstoß' um 5 Runenmacht.\n(4) Set Frost: 'Auslöschen' und 'Frostsichel' haben eine Chance von 65%, 'Tötungsmaschine' nicht aufzuzehren.\n(4) Set Unheilig: 'Dunkle Transformation' verwandelt [ Schlickspucker : Eure Monstrosität / Euren Ghul] jetzt in eine wahnsinnige Monstrosität und erhöht den Schaden sowie das Angriffstempo von Euch und der Monstrosität.\nVerkaufspreis:" }
entries[124328] = { ["name"] = "Stulpen der endlosen Wacht", ["text"] = "Wird beim Aufheben gebunden\nHände Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 55 / 55\nKlassen: Paladin\nHüterplatte der endlosen Wacht (0/5)\nKürass der endlosen Wacht\nStulpen der endlosen Wacht\nHelm der endlosen Wacht\nBeinschützer der endlosen Wacht\nSchulterplatten der endlosen Wacht\nAltes Set: Bonus ist nicht aktiv\n(2) Set Heilig: Erhöht die Menge der Heilung, die auf die Ziele Eurer Fähigkeit 'Flamme des Glaubens' übertragen wird, um 25%.\n(2) Set Schutz: Nach dem Einsatz von 'Schild des Rächers' erhaltet Ihr einen Schild in Höhe von 5.0% Eurer maximalen Gesundheit, der 10 Sek. lang anhält.\n(2) Set Vergeltung: Erhöht Euren gesamten verursachten Schaden um 2%.\n(4) Set Heilig: Jedes Mal, wenn Ihr Euer Ziel von 'Flamme des Glaubens' heilt, erhöht sich Euer Zaubertempo um 2%. Hält 6 Sek. lang an und ist 4-mal stapelbar.\n(4) Set Schutz: Euer 'Schild des Rächers' hat eine Chance von 50%, dass seine Abklingzeit nach dem Einsatz sofort abgeschlossen wird. (Procchance: 50%)\n(4) Set Vergeltung: Nach dem Einsatz von 'Zornige Vergeltung' wird Euer Schaden 10 Sek. lang alle 1 Sek. um 5% erhöht.\nVerkaufspreis:" }
