entries[124513] = { ["name"] = "Des Todes Ernte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Todesritter\nAnlegen: 'Markzerfetzer' verursacht 0 % mehr Schaden und heilt Euch um 0 % des verursachten Schadens.\nAnlegen: 'Auslöschen' verursacht 0 % zusätzlichen Schaden als Frostschaden.\nAnlegen: Eure Krankheitsticks haben eine Chance von 0 %, 'Wandernde Seuche' auszulösen und dem Ziel und allen anderen Gegnern innerhalb von 8 Metern noch einmal Schaden in gleicher Höhe zuzufügen, der gleichmäßig aufgeteilt wird.\nVerkaufspreis:" }
entries[124514] = { ["name"] = "Saat der Schöpfung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Druide\nAnlegen: 'Sternensog' hat eine Chance von 1 %, auch 'Sternenregen' auszulösen.\nAnlegen: Erhöht die Dauer von 'Tigerfuror' und 'Berserker' um 2 %.\nAnlegen: Sämtlicher erlittener Schaden wird um (Angriffskraft * 0 / 100) verringert (erhöht um Angriffskraft). Sämtlicher auf diese Weise vermiedener Schaden wird dem Angreifer als Naturschaden zugefügt. Dieser Effekt kann nicht mehr als 90% eines Angriffs absorbieren.\nAnlegen: Die Ticks Eurer Zauber 'Verjüngung' und 'Blühendes Leben' haben eine Chance von 0 %, auch andere Verbündete innerhalb von 15 Metern zu heilen.\nVerkaufspreis:" }
entries[124515] = { ["name"] = "Talisman des meisterhaften Fährtenlesers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Jäger\nAnlegen: Erhöht die Dauer von 'Zorn des Wildtiers' um 1 %.\nAnlegen: Eure Schüsse verursachen ( 0 / 100)% erhöhten Schaden pro Meter zwischen Euch und dem Ziel.\nAnlegen: Erhöht den verursachten Schaden von 'Mungobiss' um 0 %.\nVerkaufspreis:" }
entries[124516] = { ["name"] = "Foliant der wandernden Worte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Magier\nAnlegen: 'Arkane Macht' erhöht zusätzlich den Schaden und verringert die Zauberzeit und die globale Abklingzeit von 'Arkanschlag' um 0 %.\nAnlegen: 'Feuerschlag' hat eine Chance von 1 %, zusätzlich 'Flammenstoß' an der Position des Ziels zu wirken.\nAnlegen: Das Wirken von 'Eislanze' direkt nach 'Frostblitz' verursacht 1 % mehr Schaden.\nVerkaufspreis:" }
entries[124517] = { ["name"] = "Heiliger Draeneiweihrauch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Mönch\nAnlegen: Wenn Eure Gesundheit unter 1 % fällt, erhaltet Ihr eine Aufladung von 'Eisenhautgebräu'. 'Eisenhautgebräu' erhöht außerdem den verursachten Schaden um 0 %.\nAnlegen: 'Beruhigender Nebel' heilt auch Verbündete um das Ziel um 0 % der Heilung des Primärziels.\nAnlegen: Ihr habt eine Chance von 0 %, einen kostenlosen 'Tritt der aufgehenden Sonne' nach jedem Einsatz von 'Furorfäuste', 'Blackout-Tritt' oder eines normalen 'Tritt der aufgehenden Sonne' auszuführen.\nVerkaufspreis:" }
entries[124518] = { ["name"] = "Buchband der Verteidigung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Paladin\nAnlegen: Heilung mit 'Heiliger Schock' gewährt Euch 'Strahlendes Licht', was die Heilung Eurer nächsten Einsätze von 'Heiliges Licht' oder 'Lichtblitz' innerhalb von 6 Sek. um 1 % erhöht.\nAnlegen: Wenn Eure Gesundheit unter 1 % fällt, wird das Licht Euch um (Angriffskraft * 11 / 100) heilen und Gegnern in der Nähe (Angriffskraft * 11 / 100) Heiligschaden zufügen. Dieser Effekt kann nur einmal alle 12 Sek. auftreten.\nAnlegen: 'Kreuzfahrerstoß' erhöht Euren Schaden für 10 Sek. um ( 4 / 100)%. Dieser Effekt ist bis zu 3-mal stapelbar und wird zurückgesetzt, wenn Ihr für 'Kreuzfahrerstoß' ein anderes Ziel auswählt.\nVerkaufspreis:" }
entries[124519] = { ["name"] = "Kriegserklärung an den Krieg", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Priester\nAnlegen: 'Schattenheilung', 'Bittgebet', 'Machtwort: Glanz' und 'Sühne' verleihen Verbündeten zusätzlich 'Disziplin der Naaru', was den erlittenen Schaden 10 Sek. lang um 0 % verringert.\nAnlegen: Erhöht Eure durch 'Heilung' und 'Blitzheilung' hervorgerufene Heilung um 0 %.\nAnlegen: Schaden durch 'Gedankenschinden' belegt das Ziel mit 'Geistige Ermüdung', was den durch Gedankenzauber erlittenen Schaden 10 Sek. lang um ( 8 / 100)% erhöht. Dieser Effekt ist bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[124520] = { ["name"] = "Toxingefäß des Blutenden Auges", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Schurke\nAnlegen: 'Vergiften' erhöht zusätzlich die kritische Trefferchance von 'Verstümmeln' um 0 %.\nAnlegen: Eure Fähigkeit 'Durchstoßen' verursacht nun 1 % zusätzlichen Schaden.\nAnlegen: Erhöht den Schaden von 'Schattenschlag' um 1 %.\nVerkaufspreis:" }
entries[124521] = { ["name"] = "Kern der Urelemente", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Schamane\nAnlegen: Erhöht den Schaden und die Dauer von 'Flammenschock' um 1 %.\nAnlegen: Eure Windzornangriffe verursachen 4 % mehr Schaden und erzeugen 2 zusätzlichen Mahlstrom.\nAnlegen: 'Heilende Woge', 'Kettenheilung' oder 'Welle der Heilung', die auf ein Ziel gewirkt werden, das von Eurem Zauber 'Springflut' betroffen ist, haben eine Chance von 1 %, diesen Effekt von 'Springflut' auf einen weiteren Verbündeten in der Nähe auszuweiten.\nVerkaufspreis:" }
entries[124522] = { ["name"] = "Fragment des dunklen Sterns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Hexenmeister\nAnlegen: Verringert die Dauer und verkürzt das Tickintervall von 'Agonie', 'Instabiles Gebrechen' und 'Verderbnis' um 0 %.\nAnlegen: 'Hand von Gul'dan' hat eine Chance von 1 %, zusätzlich 3 Wildwichtel zu beschwören.\nAnlegen: 'Verbrennen' erhöht die kritische Trefferchance Eurer Zauber gegen dieses Ziel 10 Sek. lang um 0 %. Der Effekt ist bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[124523] = { ["name"] = "Entschlossenheit des Weltenbrechers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Krieger\nAnlegen: Eure automatischen Angriffe haben eine Chance von 0 %, die Abklingzeit von 'Kolossales Schmettern' abzuschließen.\nAnlegen: Eure automatischen Angriffe erhöhen Euer Tempo 6 Sek. lang um ( 2 / 100)%. Dieser Effekt ist bis zu 10-mal stapelbar und wird zurückgesetzt, wenn Ihr mit Euren automatischen Angriffen ein anderes Ziel attackiert.\nAnlegen: Schutz, Schutz\n'Schildblock' verringert jetzt auch erlittenen Magieschaden um 0 %. 'Zähne zusammenbeißen' erhöht jetzt auch Eure Rüstung um 0 %. 'Schildansturm' erhöht jetzt Schaden durch 'Schildschlag', 'Rache' und 'Heldenhafter Stoß' um zusätzliche 0 %.\nVerkaufspreis:" }
