entries[124540] = { ["name"] = "Bissiger Kriegskodo", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBissiger Kriegskodo : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Stachelkugel am Schwanz ist stark genug, um jede noch so stabile Allianzbefestigung zu zerschmettern.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
