entries[124632] = { ["name"] = "Glühblut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nHandwerksmaterial" }
entries[124633] = { ["name"] = "Theodrics Geheimcode", ["text"] = "Questgegenstand" }
entries[124634] = { ["name"] = "Thorasus, das steinerne Herz Draenors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 Stärke\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nBenutzen: Erweckt die Mächte aller wilden Heiligtümer, die von Euch und Euren Verbündeten getragen werden, und erhöht den verursachten Schaden 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]%.\n\nWenn dieser Effekt endet, entfesselt jeder von Macht erfüllte Spielercharakter einen Blitz aus Licht, der alle Gegner innerhalb von 20 Metern vom auslösenden Spielercharakter trifft und ihnen Schaden in Höhe von ( 27 / 100)% des gesamten Schadens, den er unter der Ermächtigung verursacht hat, zufügt. (2 Min. geteilte Abklingzeit)\n\"Eines der drei wilden Heiligtümer, geschaffen von Erzmagier Khadgar.\"\nVerkaufspreis:" }
entries[124635] = { ["name"] = "Nithramus, der Allsehende", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 Intelligenz\n+4 Ausdauer\n+ 2 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 3.\nBenutzen: Erweckt die Mächte aller wilden Heiligtümer, die von Euch und Euren Verbündeten getragen werden, und erhöht den verursachten Schaden 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]%.\n\nWenn dieser Effekt endet, entfesselt jeder von Macht erfüllte Spielercharakter einen Blitz aus Licht, der alle Gegner innerhalb von 20 Metern vom jeweiligen Spielercharakter trifft und ihnen Schaden in Höhe von ( 27 / 100)% des gesamten Schadens, den er unter der Ermächtigung verursacht hat, zufügt. (2 Min. geteilte Abklingzeit)\n\"Eines der drei wilden Heiligtümer, geschaffen von Erzmagier Khadgar.\"\nVerkaufspreis:" }
entries[124636] = { ["name"] = "Maalus, der Bluttrinker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 Beweglichkeit\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\n+ 3 Vielseitigkeit\nBenutzen: Erweckt die Mächte aller wilden Heiligtümer, die von Euch und Euren Verbündeten getragen werden, um den verursachten Schaden 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]% zu erhöhen.\n\nWenn dieser Effekt endet, entfesselt jeder von Macht erfüllte Spielercharakter einen Blitz aus Licht, der alle Gegner innerhalb von 20 Metern vom jeweiligen Spielercharakter trifft und ihnen Schaden in Höhe von ( 27 / 100)% des gesamten Schadens, den er unter der Ermächtigung verursacht hat, zufügt. (2 Min. geteilte Abklingzeit)\n\"Eines der drei wilden Heiligtümer, geschaffen von Erzmagier Khadgar.\"\nVerkaufspreis:" }
entries[124637] = { ["name"] = "Sanctus, Siegel des Ungebrochenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 [Beweglichkeit oder Stärke]\n+4 Ausdauer\n+ 2 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 3.\nBenutzen: Erweckt die Mächte der Ringe von Sanctus, die von Euch und Euren Verbündeten getragen werden, um 15 Sek. lang [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 54 / 100]% Vielseitigkeit zu gewähren.\n\nFür die Dauer dieses Effekts werden sämtlicher erlittener Schaden und alle erhaltene Heilung gleichmäßig unter den ermächtigten Verbündeten aufgeteilt. (2 Min. geteilte Abklingzeit)\nVerkaufspreis:" }
entries[124638] = { ["name"] = "Etheralus, der ewige Lohn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 3 Vielseitigkeit\nBenutzen: Erweckt die Mächte der Ringe von Etheralus, die von Euch und Euren Verbündeten getragen werden, um die hervorgerufene Heilung und Absorption 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]% zu erhöhen.\n\nWenn dieser Effekt endet, entfesselt jeder ermächtigte Spielercharakter einen Energieausbruch, der Verbündete abschirmt und Schaden in Höhe von ( 27 / 100)% der gesamten Heilung absorbiert, die der Spielercharakter während der Ermächtigung hervorgerufen hat. Der Effekt wird gleichmäßig auf alle abgeschirmten Spielercharaktere verteilt. (2 Min. geteilte Abklingzeit)\nVerkaufspreis:" }
entries[124640] = { ["name"] = "Tintenschwarzer Trank", ["text"] = "Benutzen: Verfinstert die Welt um Euch herum.\n\"Man nehme zweimal zerstoßene Grillen, einmal Dunkelmond-Tintenfischtinte und dreimal Geflüster aus den Schattenlanden.\"\nVerkaufspreis:" }
