entries[124660] = { ["name"] = "Dunkelmond-Heiltonikum", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt Gesundheit wieder her. Kann nur im Freien verwendet werden. (5 Min Abklingzeit)\n\"Heilt jedes Gebrechen und schmeckt fantastisch. Das Wundertonikum des Jahrhunderts!\"\nVerkaufspreis:" }
entries[124661] = { ["name"] = "Gladiatorenheiltrank", ["text"] = "Benutzen: Stellt Gesundheit wieder her. Kann nur im Freien verwendet werden. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[124669] = { ["name"] = "Dunkelmond-Dolchmaul", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 787500 / 5 * 20) Gesundheit und ( 1050000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\nHandwerksmaterial\n\"Jemand auf dem Dunkelmond-Jahrmarkt könnte sich dafür interessieren.\"\nVerkaufspreis:" }
entries[124670] = { ["name"] = "Versiegelte Dunkelmond-Kiste", ["text"] = "Wird beim Aufheben gebunden\n\"Auf einer Seite kann man ein stark verblichenes Dunkelmond-Auge erkennen.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[124671] = { ["name"] = "Dunkelmond-Feuerwasser", ["text"] = "Benutzen: Erhöht für 1 Stunde Eure Gewandtheit um 15% sowie Eure Größe.\n\nGewandtheit gestattet es Euch, schneller Ressourcen zu sammeln. (5 Min Abklingzeit)\n\"Erweckt das Feuer in Euch!\"\nVerkaufspreis:" }
entries[124672] = { ["name"] = "Sargeritschlüsselstein", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Macht von Sargeras fließt durch dieses teufelsbesudelte Titanengerät. Es ist ein Generalschlüssel für jede einzelne Welt der Legion. Darüber hinaus ist es Euer einziger Weg zurück zum Schwarzen Tempel.\"" }
entries[124674] = { ["name"] = "Dunkelmond-Doughnut von gestern", ["text"] = "Dauer: 1 tag\nBenutzen: Bei Anwendung auf Eure Angelrute wird Eure Angelfertigkeit 10 Min. lang um 10 erhöht.\nBenötigt Angeln (1)\n\"Lange wird sich der nicht mehr halten.\"\nVerkaufspreis:" }
